CREATE TABLE IF NOT EXISTS approved_viewers (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) UNIQUE, display_name VARCHAR(255), last_seen_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shares (id VARCHAR(64) PRIMARY KEY, video_id VARCHAR(128), recipient_email VARCHAR(255), token VARCHAR(128) UNIQUE, expires_at DATETIME, revoked TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
